head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getOpenStatus]<br/>DrillDown 이 적용되었을때 특정 Row 의 펼침 상태를 반환합니다.",
    "validation" : [
        "inputType='drilldown' 인 Column 이 정의되어야 동작합니다.",
        "rowIndex(필수) 파라미터로 펼침 상태를 조회하려는 Body Row 의 인덱스를 설정합니다.",
        "rowIndex(필수) 파라미터의 Row 인덱스는 0 부터 시작하며 바인딩 된 DataList 기준으로 인덱스가 설정됩니다.",
        "true : 파라미터에 해당하는 Row 가 펼쳐져 있는 상태입니다.",
        "false : 파라미터에 해당하는 Row 가 접힌 상태거나 자식이 없는 Leaf Row 입니다.",
        "특정 Row 가 접힌 상태이면 화면에 표시되지 않는 자식 Row 는 모두 접힌 상태가 적용됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - inputType="drilldown" 트리 컬럼 + depth(계층) 데이터로 3단계 DrillDown 그리드 구성
//  - drilldownRealRowIndexAll="true" : getOpenStatus(rowIndex) 의 rowIndex 를 화면 표시 인덱스가 아닌
//    바인딩 DataList 기준 인덱스로 처리 (엔진 gridViewApiController.getOpenStatus →
//    drilldownRealRowIndexAll 이 true 이면 getDisplayRowIndex(rowIndex) 로 DataList→표시 인덱스 변환.
//    변환 결과가 number 가 아니면(=접혀서 화면에 없으면) false 반환).
//  - 데이터(DataList idx): 영업본부(0) > 영업1팀(1) > 김영업(2), 개발본부(3) > 개발1팀(4), 관리팀(독립)(5, Leaf)
//  - showDepth="1" 로 초기에는 depth1(영업본부/개발본부/관리팀)만 표시되고 자식은 접힘
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] inputType=drilldown 트리 그리드 (drilldownRealRowIndexAll=true → rowIndex 는 화면 표시 인덱스가 아닌 DataList 기준). 데이터: 영업본부(0) > 영업1팀(1) > 김영업(2), 개발본부(3) > 개발1팀(4), 관리팀(독립)(5)=Leaf. 초기 showDepth=1 로 부모(영업본부/개발본부/관리팀)만 표시되고 자식은 접힘.\n[절차] 그리드의 +/- 아이콘으로 원하는 부모 Row 를 펼치거나 접은 뒤, par_rowIndex(DataList 인덱스) 선택 후 getOpenStatus 버튼 클릭.\n[확인] 펼쳐진 부모 Row 는 true, 접힌 부모 Row 와 자식 없는 Leaf Row 는 false. 접힌 부모의 자식(화면 미표시) Row 를 조회하면 접힘 상태(false)로 적용됨."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) ===
    //  - depth : 계층 깊이(number). drilldown 컬럼의 depthColumn 으로 사용 (본부=1, 팀=2, 사원=3)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 계층 데이터 : 부모 바로 아래에 그 자식이 위치(엔진 drilldown 은 순서 기반)
    //  - idx0 영업본부(depth1) > idx1 영업1팀(depth2) > idx2 김영업(depth3)
    //  - idx3 개발본부(depth1) > idx4 개발1팀(depth2)
    //  - idx5 관리팀(독립, depth1, 자식 없음) = Leaf
    let jsonData = [
        { "name": "영업본부",     "amount": 100, "depth": 1 },
        { "name": "영업1팀",      "amount": 110, "depth": 2 },
        { "name": "김영업",       "amount": 111, "depth": 3 },
        { "name": "개발본부",     "amount": 200, "depth": 1 },
        { "name": "개발1팀",      "amount": 210, "depth": 2 },
        { "name": "관리팀(독립)", "amount": 300, "depth": 1 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 그리드 직접 구성 (DrillDown 트리 컬럼 + drilldownRealRowIndexAll=true)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' drilldownRealRowIndexAll="true" dataList="data:dlt_bind" rowNumVisible="true" id="" style="width:560px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getOpenStatus (drilldown 펼침 상태 반환) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="360" style="" inputType="text" id="hcol1" value="조직(drilldown)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol2" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="360" style="" inputType="drilldown" depthColumn="depth" showDepth="1" depthStartIndex="1" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// [getOpenStatus] : par_rowIndex(DataList 기준 인덱스)의 펼침 상태를 true/false 로 반환
//  - true  : 해당 Row 가 펼쳐져 있는 상태
//  - false : 해당 Row 가 접힌 상태 / 자식 없는 Leaf / 접힌 부모의 화면 미표시 자식
scwin.btn_getOpenStatus_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");
    let rowIndex = parseInt(par_rowIndex.getValue(), 10);

    let result = target1.getOpenStatus(rowIndex);
    b.setReturnValue("getOpenStatus(" + rowIndex + ") 반환값 : " + result);
};
